create table if not exists public.course_grading_policies (
  id bigint generated by default as identity primary key,
  term_id text not null check (term_id ~ '^20[0-9]{2}-(0[1-9]|1[0-2])$'),
  course_code text not null check (course_code ~ '^[A-Z]{2}[0-9]{4}[A-Z]?$'),
  course_name text not null,
  policy jsonb not null,
  source_document text not null,
  source_pages int[],
  updated_at timestamptz not null default now(),
  unique (term_id, course_code)
);
alter table public.course_grading_policies enable row level security;
revoke all on public.course_grading_policies from anon, authenticated;
grant select on public.course_grading_policies to anon, authenticated;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname='public' and tablename='course_grading_policies' and policyname='Course grading policies are readable') then
    create policy "Course grading policies are readable" on public.course_grading_policies for select to anon, authenticated using (true);
  end if;
end $$;
comment on column public.course_grading_policies.policy is 'Calculator JSON with named inputs, safe expression-tree formula, and eligibility notes.';
on conflict (term_id,course_code) do update set course_name=excluded.course_name,policy=excluded.policy,source_document=excluded.source_document,source_pages=excluded.source_pages,updated_at=now();
